int N, K;
int adj[205][205];

char query(int v) {
    printf("%d\n", v);
    fflush(stdout);
    char resp[10];
    scanf("%s", resp);
    return resp[0];
}

int solve(int lo, int hi) {
    // candidates are [lo, hi] on a path
    if (lo == hi) {
        char r = query(lo);
        return (r == 'Y') ? 1 : 0;
    }
    int mid = (lo + hi) / 2;
    char r = query(mid);
    if (r == 'Y') return 1;
    if (r == 'N') {
        // not mid, not mid-1, not mid+1
        int nlo = (mid+2 <= hi) ? mid+2 : hi+1;
        if (nlo > hi) return 0; // shouldn't happen
        // try both halves excluding mid neighborhood
        return solve(lo, mid-2 > lo ? mid-2 : lo) || solve(mid+2, hi);
    }
    // Near: answer is mid-1 or mid+1
    if (mid-1 >= lo) { char r2 = query(mid-1); if(r2=='Y') return 1; }
    if (mid+1 <= hi) { char r2 = query(mid+1); if(r2=='Y') return 1; }
    return 0;
}

