public class Main {
    static int N, K;
    static List<Integer>[] adj;
    static BufferedReader br;
    static PrintWriter out;

    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out, true);

        String[] parts = br.readLine().split(" ");
        N = Integer.parseInt(parts[0]);
        K = Integer.parseInt(parts[1]);

        int M = Integer.parseInt(br.readLine());
        adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            parts = br.readLine().split(" ");
            int a = Integer.parseInt(parts[0]);
            int b = Integer.parseInt(parts[1]);
            adj[a].add(b);
            adj[b].add(a);
        }

        for (int game = 0; game < K; game++) {
            Set<Integer> candidates = new HashSet<>();
            for (int i = 1; i <= N; i++) candidates.add(i);

            while (true) {
                int guess = pickBest(candidates);
                out.println(guess);
                String response = br.readLine();

                if (response.equals("Yes")) break;
                else if (response.equals("Near")) {
                    Set<Integer> newCandidates = new HashSet<>();
                    for (int v : candidates) {
                        if (adj[guess].contains(v)) newCandidates.add(v);
                    }
                    candidates = newCandidates;
                } else { // "No"
                    Set<Integer> toRemove = new HashSet<>();
                    toRemove.add(guess);
                    toRemove.addAll(adj[guess]);
                    candidates.removeAll(toRemove);
                }
            }
        }

        br.close();
        out.close();
    }

    static int pickBest(Set<Integer> candidates) {
        if (candidates.size() == 1) return candidates.iterator().next();

        int bestVertex = -1;
        int bestWorst = Integer.MAX_VALUE;

        for (int v : candidates) {
            int cntNear = 0, cntNo = 0;
            for (int u : candidates) {
                if (u == v) continue;
                if (adj[v].contains(u)) cntNear++;
                else cntNo++;
            }
            int worst = Math.max(cntNear, cntNo);
            if (worst < bestWorst) {
                bestWorst = worst;
                bestVertex = v;
            }
        }
        return bestVertex;
    }
}

