vector<vector<int>> adj;
vector<int> parent, sub, removed;
int N;

int dfs_size(int u, int p) {
    sub[u] = 1;
    for (int v : adj[u]) {
        if (v != p && !removed[v])
            sub[u] += dfs_size(v, u);
    }
    return sub[u];
}

int find_centroid(int u, int p, int total) {
    for (int v : adj[u]) {
        if (v != p && !removed[v] && sub[v] > total / 2)
            return find_centroid(v, u, total);
    }
    return u;
}

void build_centroid_tree(int u, int par) {
    int total = dfs_size(u, -1);
    int c = find_centroid(u, -1, total);
    parent[c] = par;
    removed[c] = 1;
    for (int v : adj[c]) {
        if (!removed[v])
            build_centroid_tree(v, c);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K;
