    }

    parent.assign(N + 1, -1);
    sub.assign(N + 1, 0);
    removed.assign(N + 1, 0);

    // Build centroid tree
    build_centroid_tree(1, -1);

    // Prepare children list for centroid tree
    vector<vector<int>> children(N + 1);
    int root = -1;
    for (int i = 1; i <= N; i++) {
        if (parent[i] == -1) root = i;
        else children[parent[i]].push_back(i);
    }

    for (int game = 0; game < K; game++) {
        int cur = root;
        while (true) {
            cout << cur << endl;
            string response;
            cin >> response;
            if (response == "Yes") {
                break;
            } else if (response == "Near") {
                // The hidden vertex is adjacent to cur. 
                // In centroid tree, we must move to a child that is adjacent in original graph.
                // Since centroid tree guarantees adjacency between parent and child? Not necessarily.
                // Better approach: Use BFS from cur in original graph to find possible candidates.
                // But with constraints small, we can brute force:
                vector<int> candidates;
                for (int v : adj[cur]) {
                    candidates.push_back(v);
                }
                // Ask each candidate until we find the correct one or narrow down.
                // Since Near means one neighbor is correct, we can binary search on neighbors.
                // But neighbors ≤ N, we can ask each in worst case, but we have 10 questions total.
                // So we need a smarter method:
                // Instead, we can switch to a binary search on the original graph using BFS distances.
                // Simpler: Use a BFS ordering and binary search on distance.
                // Since N ≤ 200, we can ask each neighbor sequentially if needed.
                // But we must guarantee ≤10 questions total.
                // Let's use a BFS from cur and binary search on the BFS queue.
                vector<int> dist(N+1, -1);
                queue<int> q;
                dist[cur] = 0;
                q.push(cur);
                while (!q.empty()) {
                    int x = q.front(); q.pop();
                    for (int y : adj[x]) {
                        if (dist[y] == -1) {
                            dist[y] = dist[x] + 1;
                            q.push(y);
                        }
                    }
                }
                vector<int> order;
                for (int i = 1; i <= N; i++) if (dist[i] != -1) order.push_back(i);
                sort(order.begin(), order.end(), [&](int a, int b) {
                    return dist[a] < dist[b];
                });
                int lo = 0, hi = (int)order.size() - 1;
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    int ask = order[mid];
                    cout << ask << endl;
                    cin >> response;
                    if (response == "Yes") {
                        cur = ask;
                        goto done;
                    } else if (response == "Near") {
                        // correct is adjacent to ask, so distance from cur is dist[ask]+1 or dist[ask]-1
                        // But we can narrow: if dist[ask] < dist[correct], then correct is farther.
                        // We can just set lo = mid+1? Not safe.
                        // Instead, we switch to brute force neighbors of ask.
                        for (int nb : adj[ask]) {
                            cout << nb << endl;
                            cin >> response;
                            if (response == "Yes") {
                                cur = nb;
                                goto done;
                            }
                        }
                        // Should not reach here
                    } else {
                        // No: correct not near ask, so distance > 1 from ask.
                        // That means dist[correct] > dist[ask] + 1
                        lo = mid + 1;
                    }
                }
                // Last candidate
                cout << order[lo] << endl;
                cin >> response;
                if (response == "Yes") { cur = order[lo]; break; }
                // else fallback: ask neighbors
                for (int nb : adj[order[lo]]) {
                    cout << nb << endl;
                    cin >> response;
                    if (response == "Yes") { cur = nb; break; }
                }
                break;
            } else { // "No"
                // Move to parent in centroid tree
                cur = parent[cur];
            }
        }
        done:;
    }
    return 0;
}

