#include <bits/stdc++.h>
using namespace std;
int main(){
    int N,K;
    cin>>N>>K;
    // Build graph: vertices 1..N
    // Use binary encoding with probe vertices
    // Assign each vertex v a unique 8-bit ID (v-1), ask 8 probes
    // Probes are vertices 1..8 (or fewer if N<=8)
    // Data vertices: 9..N
    // Probe i connected to vertex v if bit i of (v-1) is set
    int BITS=8;
    vector<pair<int,int>> edges;
    for(int v=1;v<=N;v++)
        for(int b=0;b<BITS;b++)
            if((v-1)>>b&1) edges.push_back({b+1,v}); // probe b+1 to v, but avoid self-loops
    // Remove self-loops
    vector<pair<int,int>> real_edges;
    for(auto e:edges) if(e.first!=e.second) real_edges.push_back(e);
    // Also need probes to have unique signatures among themselves
    // Probe p (1-indexed): its ID is p-1, bits of p-1
    // When we ask probe q about target=probe p: Near iff p-1 has bit q-1 set AND p!=q
    cout<<real_edges.size()<<"\n";
    for(auto e:real_edges) cout<<e.first<<" "<<e.second<<"\n";
    cout.flush();
    for(int g=0;g<K;g++){
        vector<int> cands;
        for(int i=1;i<=N;i++) cands.push_back(i);
        bool found=false;
        for(int q=0;q<10&&!found;q++){
            // Ask the first candidate
            int ask=cands[0];
            cout<<ask<<"\n"; cout.flush();
            string resp; cin>>resp;
            if(resp=="Yes"){found=true;break;}
            vector<int> next;
            if(resp=="Near"){
                // target is adjacent to ask
                // find neighbors of ask
                set<int> nbrs;
                for(auto e:real_edges){
                    if(e.first==ask) nbrs.insert(e.second);
                    if(e.second==ask) nbrs.insert(e.first);
                }
                for(int c:cands) if(c!=ask&&nbrs.count(c)) next.push_back(c);
            } else {
                // No: target is not ask and not adjacent
                set<int> nbrs;
                for(auto e:real_edges){
                    if(e.first==ask) nbrs.insert(e.second);
                    if(e.second==ask) nbrs.insert(e.first);
                }
                for(int c:cands) if(c!=ask&&!nbrs.count(c)) next.push_back(c);
            }
            cands=next;
        }
    }
}
